'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dlanst = require( './../lib/dlanst.js' );


// VARIABLES //

var NORMS = [
	'max',
	'one-norm',
	'infinity-norm',
	'frobenius-norm'
];
var options = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} norm - specifies the norm to be returned
* @param {PositiveInteger} len - array length
* @returns {Function} benchmark function
*/
function createBenchmark( norm, len ) {
	var D = uniform( len, -100.0, 100.0, options );
	var E = uniform( len - 1, -100.0, 100.0, options );
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var out;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			out = dlanst( norm, len, D, 1, E, 1 );
			if ( isnan( out ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( out ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var norm;
	var len;
	var min;
	var max;
	var f;
	var i;
	var j;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( j = 0; j < NORMS.length; j++ ) {
		norm = NORMS[ j ];
		for ( i = min; i <= max; i++ ) {
			len = pow( 10, i );
			f = createBenchmark( norm, len );
			bench( format( '%s:norm=%s,len=%d', pkg, norm, len ), f );
		}
	}
}

main();
